<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, paths, displayDate } from '../api'
import RoleCard from '../components/RoleCard.vue'
const form = reactive({ expected_version: 0, major: '数据科学与大数据技术', graduation_year: 2027, stage: 'studying', degree: 'bachelor', english: 'unknown', internship_months: null, summary: '', skills: [], cities: [], intents: ['employment'] })
const skills = ref(''), cities = ref(''), history = ref([]), role = ref(null), portrait = ref(null), error = ref(''), message = ref(''), busy = ref(false), loaded = ref(false)
function apply(p) { if (p) { Object.assign(form, p, { expected_version: p.version }); skills.value = p.skills.join('、'); cities.value = p.cities.join('、') } }
async function load() {
  try { const [p,h,r,t] = await Promise.all([api('/profile'), api('/profile/history'), api('/profile/roles'),api('/profile/portrait')]); apply(p); history.value = h; role.value = r; portrait.value = t; loaded.value = true }
  catch(e) { error.value = e.message }
}
async function save() {
  busy.value = true; error.value = ''; message.value = ''
  try {
    const payload = { ...form, skills: skills.value.split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean), cities: cities.value.split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean), internship_months: form.internship_months === '' ? null : form.internship_months }
    const p = await api('/profile', { method: 'PUT', body: payload }); apply(p)
    const [h,r,t] = await Promise.all([api('/profile/history'),api('/profile/roles'),api('/profile/portrait')]); history.value = h; role.value = r; portrait.value = t; message.value = `画像 V${p.version} 已保存，之前版本仍可查看。`
  } catch(e) { error.value = e.message } finally { busy.value = false }
}
async function updateDisplay(body) { busy.value = true; error.value = ''; try { role.value = await api('/profile/roles/display',{method:'PATCH',body}); message.value = '已更新私人伙伴展示，问卷原始结果保持不变。' } catch(e) { error.value = e.message } finally { busy.value = false } }
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">MY PROFILE</div><h1>认识自己，也记录变化<span class="heading-dot">.</span></h1><p>私人画像仅本人可见。技能为自报信息，不产生未经测量的能力分数。</p></div><span class="tag">{{ form.expected_version ? `当前 V${form.expected_version}` : '尚未保存' }}</span></div><div v-if="error" class="alert error" role="alert">{{ error }}<button class="ghost" @click="load">重新加载</button></div><div v-if="message" class="alert success" role="status">{{ message }}</div><section v-if="portrait" class="panel profile-portrait"><div class="panel-heading"><h2>从你的经历，看见实践方向</h2><span class="tag">自报画像 V{{ portrait.profile_version }}</span></div><div v-if="portrait.observable_tags.length" class="portrait-tag-grid"><article v-for="t in portrait.observable_tags" :key="t.name"><span class="portrait-tag-icon">◇</span><div><h3>{{ t.name }}</h3><p>{{ t.reason }}</p><span class="muted">来源：你填写的技能组合</span></div></article></div><p v-else class="muted">尚未匹配到实践方向标签。填写具体技能与项目经历，可以帮助解释你的背景。</p><p class="data-note">{{ portrait.notice }}</p><div class="portrait-completion"><span>可选信息已填 {{ portrait.profile_completeness.filled }} / {{ portrait.profile_completeness.total }} 项</span><p v-if="portrait.profile_completeness.missing.length">可继续补充：{{ portrait.profile_completeness.missing.join('、') }}</p><RouterLink to="/decisions">比较我的发展路径 →</RouterLink></div></section><div class="profile-layout"><form class="panel profile-form" @submit.prevent="save"><h2>基本信息</h2><div class="form-grid"><label>专业<input v-model="form.major" required maxlength="100"></label><label>毕业届次<input v-model.number="form.graduation_year" type="number" min="2000" max="2100" required></label><label>当前阶段<select v-model="form.stage"><option value="studying">在校</option><option value="internship">准备实习</option><option value="job_seeking">求职中</option><option value="exam_preparation">备考中</option><option value="graduated">已毕业</option></select></label><label>当前 / 在读学历<select v-model="form.degree"><option value="junior_college">专科</option><option value="bachelor">本科</option><option value="master">硕士</option><option value="doctor">博士</option></select></label><label>英语情况<select v-model="form.english"><option value="unknown">未填写 / 未知</option><option value="cet4">自报 CET-4</option><option value="cet6">自报 CET-6</option><option value="other">其他</option></select></label><label>实习月数（可留空）<input v-model.number="form.internship_months" type="number" min="0" max="120" placeholder="未填写代表未知"></label></div><hr><h2>技能与偏好</h2><label>已掌握技能<input v-model="skills" placeholder="Python、SQL、MySQL（用顿号或逗号分隔）" maxlength="2000"></label><label>偏好城市<input v-model="cities" placeholder="衡阳、长沙（可填写多个）" maxlength="1000"></label><fieldset><legend>发展意向（可多选）</legend><div class="choice-group"><label v-for="p in ['employment','postgraduate','civil_service','public_institution','internship']" :key="p" class="choice"><input type="checkbox" v-model="form.intents" :value="p">{{ paths[p] }}</label></div></fieldset><label>项目与经历说明<textarea v-model="form.summary" rows="4" maxlength="3000" placeholder="简要记录已完成的项目和经历；请勿填写身份证号等敏感信息。"></textarea></label><button class="button" :disabled="busy || !loaded || !form.intents.length">{{ busy ? '保存中…' : '保存新版本 →' }}</button></form><aside><RoleCard :snapshot="role" editable :busy="busy" @display="updateDisplay"/><div class="panel history-panel"><div class="panel-heading"><h2>画像时间线</h2><span class="tag">{{ history.length }} 个版本</span></div><p class="muted">意向变化会形成新版本，不覆盖过去。</p><div v-if="!history.length" class="empty">保存后，你的成长轨迹会出现在这里。</div><details v-for="p in history" :key="p.version" class="timeline-item"><summary><strong>V{{ p.version }}</strong> · {{ displayDate(p.valid_from) }} <span>{{ p.valid_to ? '历史' : '当前' }}</span></summary><p>{{ p.major }} · {{ p.graduation_year }} 届</p><p>{{ p.intents.map(i=>paths[i]).join('、') }}</p><p>城市：{{ p.cities.join('、') || '未知' }}</p><p>技能：{{ p.skills.join('、') || '未知' }}</p></details></div></aside></div></template>
